'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v).toLocaleString('sr-RS')+' RSD',date=v=>new Intl.DateTimeFormat('sr-Latn-RS',{timeZone:'Europe/Belgrade',day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v));
const cancelLink=token=>location.pathname+'?cancel='+encodeURIComponent(token);
let currentUser=null,authEpoch=0,authBusy=false,authRole='client',authMode='login',authPortal=false;
let authSyncRequest=0,authChannel=null,authSyncTimer=null,demoQuickLogin=false,accountRequest=0,accountBusy=false,accountProfile=null;
let notificationRequest=0,notificationBusy=false,notificationItems=[],unreadCount=0,portalDate='',portalEditing=false,accountEditing=false,lastPortalData=null,pollActive=false,bookingSignature='';
let groups=[],districts={},active,service='',city='Beograd',expanded=false,request=0,bookingRequest=0,reminderRequest=0,profileRequest=0,portalRequest=0,controller,busy=false,cancelBusy=false,reviewBusy=false,portalBusy=false,currentBookings=[],portalClinic='',reviewBookingId='';
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await r.json()}catch{throw new Error('Server je vratio neispravan odgovor.')}if(!r.ok){const messages={401:'Prijavite se odgovarajućim nalogom da biste nastavili.',400:'Proverite unete podatke i pokušajte ponovo.',403:'Ova radnja nije dozvoljena u ovoj sesiji.',404:'Traženi podatak više nije dostupan.',409:'Termin ili rezervacija su u međuvremenu promenjeni. Osvežite podatke.'};const e=new Error([400,409,429].includes(r.status)&&typeof data.error==='string'?data.error:(messages[r.status]||'Zahtev nije uspeo. Pokušajte ponovo.'));e.status=r.status;throw e}return data}
function errorBox(message,retry){const box=document.createElement('div');box.className='empty';box.setAttribute('role','alert');const p=document.createElement('p');p.textContent=message;box.append(p);if(retry){const b=document.createElement('button');b.className='text-button';b.textContent='Pokušaj ponovo ↗';b.onclick=retry;box.append(b)}return box}
function setServices(){const g=groups.find(g=>g[0]==$('#group').value);if(g)$('#service').innerHTML=g[3].map(s=>`<option>${esc(s)}</option>`).join('')}
function setDistricts(){const previous=$('#district').value;$('#district').innerHTML='<option value="">Sve opštine</option>'+(districts[$('#city').value]||[]).map(s=>`<option>${esc(s)}</option>`).join('');if((districts[$('#city').value]||[]).includes(previous))$('#district').value=previous}
function tiles(){$('#group-grid').innerHTML=(expanded?groups:groups.slice(0,6)).map(g=>`<button class="group-tile ${g[0]===active?.[0]?'active':''}" aria-pressed="${g[0]===active?.[0]}" data-id="${esc(g[0])}"><span class="symbol" aria-hidden="true">${medicalIcon(g[0])}</span><b>${esc(g[1])}</b><small>${g[3].length} vrste usluga ↗</small></button>`).join('');$('#group-grid').querySelectorAll('button').forEach(b=>b.onclick=()=>{ $('#group').value=b.dataset.id;setServices();search();$('#results').scrollIntoView({behavior:'smooth'}) });$('#all-groups').textContent=expanded?'Prikaži manje grupa ↑':`Prikaži sve medicinske grupe (${groups.length}) ↓`;$('#all-groups').setAttribute('aria-expanded',String(expanded))}
async function search(){active=groups.find(g=>g[0]==$('#group').value);if(!active)return;service=$('#service').value;city=$('#city').value;tiles();await loadOffers()}
async function loadOffers(){if(!active)return;const id=++request;controller?.abort();controller=new AbortController();const allDoctors=$('#doctor-query').value.trim()&&$('#doctor-all').checked;const context={group:active,service,city,allDoctors};$('#result-title').textContent=`${allDoctors?'Pretraga lekara kroz sve specijalnosti':service}, ${city}`;$('#price-label').textContent=money($('#price').value);$('#cards').setAttribute('aria-busy','true');$('#cards').textContent='Učitavanje slobodnih termina…';$('#result-count').textContent='Provera dostupnosti…';try{const q=new URLSearchParams({group:allDoctors?'all':active[0],service:allDoctors?'':service,city,day:$('#day').value,maxPrice:$('#price').value,sort:$('#sort').value,district:$('#district').value,minRating:$('#min-rating').value||'0',doctor:$('#doctor-query').value,discountOnly:String($('#last-minute').checked)});const data=await api('/api/offers?'+q,{signal:controller.signal});if(id!==request)return;if(!Array.isArray(data.offers))throw new Error('Ponuda nije dostupna.');renderOffers(data.offers,context);$('#result-count').textContent=`${data.offers.length} demo ordinacije · ${allDoctors?'Sve specijalnosti':context.group[1]} · vreme za Srbiju`}catch(e){if(id!==request||e.name==='AbortError')return;$('#result-count').textContent='Termini nisu učitani.';$('#cards').replaceChildren(errorBox(e.message,loadOffers))}finally{if(id===request)$('#cards').setAttribute('aria-busy','false')}}
function ratingText(rating,count){return rating===null||rating===undefined||!Number(count)?'Još nema potvrđenih recenzija':`★ ${Number(rating).toLocaleString('sr-RS',{maximumFractionDigits:1})} · ${Number(count)} potvrđenih recenzija`}
function renderOffers(offers,c){if(!offers.length){$('#cards').innerHTML='<div class="empty"><h3>Nema termina uz izabrane filtere</h3><p>Promenite vremenski period, opštinu, ocenu, lekara ili cenu.</p><button id="empty-reset" class="text-button">Poništi filtere ↗</button></div>';$('#empty-reset').onclick=resetFilters;return}$('#cards').innerHTML=offers.map((o,i)=>`<article class="card"><div class="clinic-icon" aria-hidden="true">${medicalIcon(o.groupId||c.group[0])}</div><div><div class="card-topline">${esc(o.groupName||o.doctor?.specialty||c.group[1])} · DEMO ORDINACIJA</div><h3><button class="profile-link" data-profile="${i}">${esc(o.name)} ↗</button></h3><div class="location">⌖ ${esc(o.location)}</div><div class="doctor-line">${esc(o.doctor?.name||'Demo lekar')} · ${esc(o.doctor?.specialty||c.group[1])}</div><div class="rating-line">${esc(ratingText(o.rating,o.reviewCount))}</div><div class="service-name">${esc(o.service||c.service)}</div><div class="inclusions">Dodatne analize nisu uključene. Profil ordinacije sadrži opis usluge i lekara.</div><div class="slots">${o.slots.map((s,j)=>`<button class="slot ${s.discountPercent>0?'discounted':''}" data-offer="${i}" data-slot="${j}">${esc(date(s.startsAt))}<strong>${esc(money(s.cost??o.cost))}</strong>${s.discountPercent>0?`<small><del>${esc(money(s.originalCost))}</del><span class="discount-badge">−${esc(s.discountPercent)}% · last minute</span></small>`:'<small>Redovna demo cena</small>'}</button>`).join('')}</div></div><div class="price-side"><small>Od</small><strong>${esc(money(o.cost))}</strong><span class="tag">${o.slots.length} slobodnih termina</span></div></article>`).join('');$('#cards').querySelectorAll('.slot').forEach(b=>b.onclick=()=>{const o=offers[Number(b.dataset.offer)];book(o.slots[Number(b.dataset.slot)],o,{...c,service:o.service||c.service})});$('#cards').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>showClinic(offers[Number(b.dataset.profile)].clinicId))}
function setBusy(value){busy=value;$('#booking').setAttribute('aria-busy',String(value));$('#booking .close').disabled=value;const b=$('#confirm');if(b){b.disabled=value||!$('#ack')?.checked||!$('#consent')?.checked;b.textContent=value?'Čuvanje rezervacije…':'Sačuvaj demo rezervaciju ↗'}$('#guest-form')?.querySelectorAll('input').forEach(input=>input.disabled=value)}
function book(slot,o,c){if(busy)return;if(currentUser?.role==='clinic'){openAuth('client');$('#auth-help').textContent+='; Za pregled pacijenta prijavite se kao klijent, ili zatvorite prijavu i odjavite se da biste zakazali kao gost.';return}$('#booking-content').innerHTML=`<div class="eyebrow">DEMO REZERVACIJA BEZ NALOGA</div><h2 id="booking-title">Potvrdite demo termin.</h2><div class="summary">${esc(o.name)}<br><b>${esc(c.service)}</b><br>${esc(o.doctor?.name||'Demo lekar')}<br>${esc(c.city)} · ${esc(date(slot.startsAt))}<strong>${esc(money(slot.cost??o.cost))}</strong>${slot.discountPercent>0?`<small>Redovna cena <del>${esc(money(slot.originalCost))}</del> · −${esc(slot.discountPercent)}%</small>`:''}</div><p>Unesite <b>izmišljene kontakt podatke</b> za test. Ne unosite stvarne lične ili zdravstvene podatke. ${currentUser?.role==='client'?'Rezervacija će biti vezana za vaš lokalni klijentski nalog. Nalog nema potvrdu e-mail adrese.':'Bez naloga rezervacija ostaje u ovoj sesiji pregledača. Možete se opciono prijaviti za istoriju na klijentskom nalogu.'}</p>${!currentUser?'<p><button id="booking-sign-in" type="button" class="auth-inline">Opciono: prijava ili registracija klijenta</button></p>':''}<form id="guest-form" class="stack-form"><label>Demo ime i prezime<input id="guest-name" type="text" autocomplete="off" placeholder="Demo Pacijent" minlength="2" maxlength="100" required></label><label>Demo telefon<input id="guest-phone" type="tel" autocomplete="off" placeholder="0600000000" minlength="6" maxlength="30" required></label><label>Demo e-mail<input id="guest-email" type="email" autocomplete="off" placeholder="demo@example.com" maxlength="254" required></label><label class="check"><input id="consent" type="checkbox" required> Saglasan/na sam da se ovi izmišljeni kontakti sačuvaju lokalno za demo rezervaciju.</label><label class="check"><input id="ack" type="checkbox" required> Razumem da nema stvarnog pregleda, SMS/Viber slanja ili naplate.</label><div id="booking-error" role="alert"></div><button id="confirm" class="primary" type="submit" disabled>Sačuvaj demo rezervaciju ↗</button></form>`;if(currentUser?.role==='client'){$('#guest-name').value=currentUser.name||'';$('#guest-email').value=currentUser.email||'';$('#guest-phone').value=accountProfile?.phone||''}if($('#booking-sign-in'))$('#booking-sign-in').onclick=()=>openAuth('client');['#ack','#consent'].forEach(s=>$(s).onchange=()=>{if(!busy)setBusy(false)});$('#guest-form').onsubmit=async e=>{e.preventDefault();if(busy||!$('#ack').checked||!$('#consent').checked)return;const guest={name:$('#guest-name').value.trim(),phone:$('#guest-phone').value.trim(),email:$('#guest-email').value.trim()};if(guest.name.length<2||guest.phone.length<6){$('#booking-error').textContent='Unesite demo ime (bar 2 znaka) i telefon (bar 6 znakova).';return}setBusy(true);$('#booking-error').textContent='';try{const {booking:b}=await api('/api/bookings',{method:'POST',body:JSON.stringify({slotId:slot.id,ack:true,consent:true,guest})});$('#booking-content').innerHTML=`<div class="success-icon">✓</div><div class="eyebrow">${currentUser?'SAČUVANO NA KLIJENTSKOM NALOGU':'SAČUVANO ZA OVU SESIJU'}</div><h2 id="booking-title">Zahtev je poslat — čeka potvrdu ordinacije.</h2><p>${esc(b.service)}<br>${esc(b.clinic)}<br>${esc(date(b.startsAt))}</p><div class="prototype-note">Čeka se odluka demo ordinacije. Ovo nije stvaran pregled. Demo SMS/Viber podsetnici su samo planirane lokalne stavke; poruke se ne šalju.</div>${b.cancelToken?`<p><a class="cancel-link" href="${esc(cancelLink(b.cancelToken))}">Link za otkazivanje demo rezervacije</a></p>`:''}<button id="back" class="text-button">Moje rezervacije ↗</button>`;$('#back').onclick=()=>{$('#booking').close();$('#my-bookings').scrollIntoView({behavior:'smooth'})};await Promise.all([loadOffers(),loadBookings(),loadReminders(),loadNotifications()])}catch(error){$('#booking-error').textContent=error.status===409?'Termin više nije dostupan. Zatvorite prozor i izaberite drugi termin.':error.message;if(error.status===409){$('#ack').checked=false;await loadOffers()}}finally{setBusy(false)}};$('#booking').showModal()}
function statusText(status){return({pending:'Čeka potvrdu ordinacije',booked:'Potvrđeno',completed:'Obavljeno u demou',rejected:'Odbijeno',cancelled:'Otkazano'})[status]||'Demo rezervacija'}
async function loadBookings(silent=false){const id=++bookingRequest,epoch=authEpoch;if(currentUser?.role==='clinic'){currentBookings=[];$('#booking-list').textContent='Ordinacijski nalog koristi portal za klinike. Za lične rezervacije prijavite se kao klijent.';$('#booking-status').textContent='';return}$('#booking-list').setAttribute('aria-busy','true');if(!silent)$('#booking-list').textContent='Učitavanje rezervacija…';try{const {bookings}=await api('/api/bookings');if(id!==bookingRequest||epoch!==authEpoch)return;if(!Array.isArray(bookings))throw new Error('Rezervacije nisu dostupne.');bookings.sort(compareBookings);const signature=JSON.stringify(bookings.map(b=>[b.id,b.status,b.reviewed,b.rejectionReason]));if(bookingSignature&&bookingSignature!==signature)showAccountRefreshNotice();bookingSignature=signature;currentBookings=bookings;$('#booking-list').innerHTML=bookings.length?bookings.map((b,i)=>`<article class="reservation"><div><span class="status-badge">${esc(statusText(b.status))}</span><h3>${esc(b.service)}</h3><p>${esc(b.clinic)} · ${esc(b.city)}<br>${esc(b.doctorName||'Demo lekar')}<br>${esc(date(b.startsAt))} · <b>${esc(money(b.cost))}</b></p><small>${currentUser?'Demo rezervacija naloga':'Sesijska demo rezervacija'} · ${esc(b.id)}</small>${b.status==='rejected'?`<div class="rejection-note">Razlog odbijanja: ${esc(b.rejectionReason||'Razlog nije naveden.')}</div>`:''}</div><div class="reservation-actions">${['pending','booked'].includes(b.status)?`<button class="cancel-button" data-cancel="${i}">Otkaži rezervaciju</button>`:''}${b.status==='completed'&&!b.reviewed?`<button class="slot" data-review="${i}">Ostavi recenziju</button>`:''}${b.reviewed?'<span class="inline-note">Recenzija je sačuvana.</span>':''}${['pending','booked'].includes(b.status)&&b.cancelToken?`<a class="cancel-link" href="${esc(cancelLink(b.cancelToken))}">Link za otkazivanje</a>`:''}</div></article>`).join(''):'<div class="empty">Još nemate demo rezervacija za ovaj nalog ili sesiju.</div>';$('#booking-list').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>confirmCancellation(bookings[Number(b.dataset.cancel)]));$('#booking-list').querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openReview(bookings[Number(b.dataset.review)]));$('#booking-status').textContent=`${currentUser?'Demo rezervacije klijentskog naloga':'Demo rezervacije u ovoj sesiji'}: ${bookings.length}.`}catch(e){if(id!==bookingRequest||epoch!==authEpoch)return;$('#booking-list').replaceChildren(errorBox(e.message,loadBookings));$('#booking-status').textContent='Rezervacije nisu učitane.'}finally{if(id===bookingRequest&&epoch===authEpoch)$('#booking-list').setAttribute('aria-busy','false')}}
async function loadReminders(){const id=++reminderRequest,epoch=authEpoch;if(currentUser?.role==='clinic'){$('#reminder-list').textContent='Pacijentski podsetnici nisu dostupni ordinacijskom nalogu.';return}$('#reminder-list').textContent='Učitavanje demo podsetnika…';try{const {reminders}=await api('/api/reminders');if(id!==reminderRequest||epoch!==authEpoch)return;$('#reminder-list').innerHTML=reminders.length?'<ul>'+reminders.map(r=>`<li><b>${esc(r.channel)}</b> · planirano ${esc(date(r.scheduledAt))} · demo, nije poslato<br>${esc(r.message)}${/^\/\?cancel=[a-f0-9]{64}$/.test(r.cancelUrl||'')?`<br><a class="cancel-link" href="${esc(r.cancelUrl)}">Otvori potvrdu otkazivanja ↗</a>`:''}</li>`).join('')+'</ul>':'<p>Nema planiranih demo podsetnika za ovu sesiju.</p>'}catch(e){if(id===reminderRequest&&epoch===authEpoch)$('#reminder-list').replaceChildren(errorBox(e.message,loadReminders))}}
function confirmCancellation(b){if(cancelBusy)return;const token=b.cancelToken;if(!token){$('#booking-status').textContent='Link za otkazivanje nije dostupan. Osvežite rezervacije.';return}$('#cancel-description').textContent=b.startsAt?`${b.service} · ${b.clinic} · ${date(b.startsAt)}`:'Otkazivanje demo rezervacije putem privatnog linka. Potvrdite samo ako želite da otkažete ovaj termin.';$('#cancel-error').textContent='';$('#cancel-confirm').disabled=false;$('#cancel-confirm').textContent='Da, otkaži rezervaciju';$('#cancel-dialog').showModal();$('#cancel-confirm').onclick=async()=>{if(cancelBusy)return;cancelBusy=true;$('#cancel-dialog').setAttribute('aria-busy','true');['#cancel-confirm','#cancel-back','#cancel-dialog .close'].forEach(s=>$(s).disabled=true);$('#cancel-confirm').textContent='Otkazivanje…';try{await api('/api/cancel/'+encodeURIComponent(token),{method:'DELETE'});$('#cancel-dialog').close();if(new URLSearchParams(location.search).has('cancel'))history.replaceState(null,'',location.pathname);await Promise.all([loadBookings(),loadOffers(),loadReminders(),loadNotifications()]);$('#booking-status').textContent='Demo rezervacija je otkazana.'}catch(e){$('#cancel-error').textContent=e.message;$('#cancel-confirm').textContent='Pokušaj ponovo'}finally{cancelBusy=false;$('#cancel-dialog').setAttribute('aria-busy','false');['#cancel-confirm','#cancel-back','#cancel-dialog .close'].forEach(s=>$(s).disabled=false)}}}
async function showClinic(clinicId){if(!clinicId)return;const id=++profileRequest;$('#clinic-content').innerHTML='<h2 id="clinic-title">Učitavanje profila ordinacije…</h2>';$('#clinic-content').setAttribute('aria-busy','true');if(!$('#clinic-dialog').open)$('#clinic-dialog').showModal();try{const {clinic:c}=await api('/api/clinics/'+encodeURIComponent(clinicId));if(id!==profileRequest)return;$('#clinic-content').innerHTML=`<div class="eyebrow">IZMIŠLJENA DEMO ORDINACIJA</div><h2 id="clinic-title">${esc(c.name)}</h2><div class="clinic-illustration"><svg viewBox="0 0 160 120" aria-hidden="true"><rect x="25" y="30" width="110" height="80" rx="5" fill="#bdd4bd"/><rect x="47" y="10" width="66" height="100" rx="5" fill="#f9fcf4"/><path d="M73 24h14v13h13v14H87v13H73V51H60V37h13z" fill="#14786a"/><path d="M66 110V80h28v30" fill="#82aa91"/><path d="M32 49h9v12h-9zm0 25h9v12h-9zm87-25h9v12h-9zm0 25h9v12h-9z" fill="#f9fcf4"/></svg><small>Demo ilustracija.<br>Nije fotografija stvarne klinike.</small></div><p>${esc(c.address)} · ${esc(c.district)}, ${esc(c.city)}<br><b>Demo adresa — nije potvrđena lokacija ordinacije.</b></p><p class="inline-note">Adresa je prikazana lokalno. Online mapa nije uključena.</p><p>${esc(c.description||'')}</p><p class="inline-note">Demo kontakt: ${esc(c.phone||'Nije naveden')}</p><div class="rating-line">${esc(ratingText(c.rating,c.reviewCount))}</div><div class="amenities"><span>Parking: ${esc(c.parking||'Nema podataka')}</span><span>${c.accessible?'Pristupačan ulaz (demo podatak)':'Pristupačnost nije potvrđena'}</span></div><h3>Usluge i sadržaj pregleda</h3><ul>${(c.inclusions||[]).map(t=>`<li class="inline-note">${esc(t)}</li>`).join('')}</ul><h3>Lekari</h3><div class="profile-doctors">${(c.doctors||[]).map(d=>`<article><h3>${esc(d.name)}</h3><p>${esc(d.specialty)}<br>${esc(d.bio)}</p><small>Demo profil lekara; isti lekar može raditi u više ordinacija.</small></article>`).join('')}</div><h3>Potvrđene demo recenzije</h3><p class="inline-note">Recenzije nastaju isključivo iz rezervacija koje su označene kao obavljene u ovom lokalnom demou. Nisu dokaz stvarnog pregleda.</p><div class="reviews-list">${(c.reviews||[]).filter(r=>r.verified===true).map(r=>`<article class="review-card"><b>★ ${esc(r.rating)} / 5 · Potvrđena demo rezervacija</b><p>${esc(r.comment||'Bez komentara.')}</p><small>${esc(date(r.createdAt))}</small></article>`).join('')||'<p>Još nema potvrđenih recenzija.</p>'}</div>`}catch(e){if(id===profileRequest){$('#clinic-content').innerHTML='<h2 id="clinic-title">Profil nije učitan</h2>';$('#clinic-content').append(errorBox(e.message,()=>showClinic(clinicId)))}}finally{if(id===profileRequest)$('#clinic-content').setAttribute('aria-busy','false')}}
function openReview(booking){if(reviewBusy||booking.status!=='completed'||booking.reviewed)return;reviewBookingId=booking.id;$('#review-form').reset();$('#review-error').textContent='';$('#review-dialog').showModal()}
async function submitReview(e){e.preventDefault();if(reviewBusy)return;const rating=$('input[name="rating"]:checked');if(!rating)return;reviewBusy=true;$('#review-dialog').setAttribute('aria-busy','true');$('#review-submit').disabled=true;$('#review-submit').textContent='Čuvanje recenzije…';$('#review-dialog .close').disabled=true;$('#review-error').textContent='';try{await api('/api/reviews',{method:'POST',body:JSON.stringify({bookingId:reviewBookingId,rating:Number(rating.value),comment:$('#review-comment').value.trim()})});$('#review-dialog').close();await Promise.all([loadBookings(),loadOffers()]);$('#booking-status').textContent='Recenzija je sačuvana za obavljenu demo rezervaciju.'}catch(error){$('#review-error').textContent=error.message;if(error.status===409)await loadBookings()}finally{reviewBusy=false;$('#review-dialog').setAttribute('aria-busy','false');$('#review-submit').disabled=false;$('#review-submit').textContent='Sačuvaj recenziju';$('#review-dialog .close').disabled=false}}
async function loadPortal(clinicId=portalClinic){if(currentUser?.role!=='clinic'){$('#portal-content').textContent='Portal je dostupan samo prijavljenoj ordinaciji.';return}clinicId=currentUser.clinicId;const id=++portalRequest,epoch=authEpoch;$('#portal-content').setAttribute('aria-busy','true');$('#portal-content').textContent='Učitavanje portala…';try{const data=await api('/api/portal'+(clinicId?'?clinicId='+encodeURIComponent(clinicId):''));if(id!==portalRequest||epoch!==authEpoch)return;portalClinic=data.clinicId;$('#portal-account').textContent='Prijavljena ordinacija: '+(currentUser.clinicName||currentUser.name)+'. Prikazuju se samo njeni podaci.';$('#portal-clinic').innerHTML=data.clinics.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('#portal-clinic').value=portalClinic;renderPortal(data)}catch(error){if(id!==portalRequest||epoch!==authEpoch)return;if(error.status===401||error.status===403){await syncAuth();$('#booking-status').textContent='Pristup portalu zahteva aktivnu prijavu ordinacije.';if(currentUser?.role!=='clinic'){$('#partner-dialog').close();openAuth('clinic',true)}else $('#portal-content').replaceChildren(errorBox('Sesija ordinacije nije aktivna. Prijavite se ponovo.',()=>openAuth('clinic',true)))}else $('#portal-content').replaceChildren(errorBox(error.message,()=>loadPortal(clinicId)))}finally{if(id===portalRequest&&epoch===authEpoch)$('#portal-content').setAttribute('aria-busy','false')}}
function renderPortal(data){const s=data.stats;$('#portal-content').innerHTML=`<div id="portal-error" role="alert"></div><div class="portal-stats"><div>Demo rezervacije<strong>${esc(s.bookings)}</strong></div><div>Obavljeni demo pregledi<strong>${esc(s.completed)}</strong></div><div>Vrednost obavljenih demo pregleda<strong>${esc(money(s.revenue))}</strong></div></div><p class="inline-note">Potencijalna vrednost: ${esc(money(s.potentialRevenue))}. Iznosi su demo statistika; nema naplate.</p><h3>Tražene usluge</h3><ul>${(s.popular||[]).map(p=>`<li class="inline-note">${esc(p.service)} · ${esc(p.count)} rezervacija</li>`).join('')||'<li class="inline-note">Još nema podataka.</li>'}</ul><h3>Prazni termini po satu</h3><p class="inline-note">${(s.emptyHours||[]).map(h=>`${esc(h.hour)}h: ${esc(h.count)} termina`).join(' · ')||'Nema dostupnih podataka.'}</p><h3>Demo kalendar ordinacije</h3><p class="inline-note">Blokirajte ili omogućite slobodan termin. Zauzet termin se ne može menjati ovde. Isti lekar može imati termine u više klinika.</p><div class="portal-slots">${data.slots.map((slot,i)=>`<article class="portal-slot ${!slot.enabled?'blocked':''}"><b>${esc(date(slot.startsAt))}</b><br>${esc(slot.service)}<br>${!slot.enabled?'Blokiran':slot.available?'Slobodan':'Zauzet ili nedostupan'}<button data-toggle="${i}" ${!slot.available&&slot.enabled?'disabled':''}>${slot.enabled?'Blokiraj termin':'Omogući termin'}</button></article>`).join('')||'<p>Nema termina u ovom periodu.</p>'}</div><h3>Rezervacije ordinacije</h3>${data.bookings.map((b,i)=>`<article class="portal-booking"><b>${esc(b.service)}</b> · ${esc(statusText(b.status))}<br>${esc(b.doctorName||'Demo lekar')} · ${esc(date(b.startsAt))} · ${esc(money(b.cost))}<br><small>ID ${esc(b.id)}</small>${b.patient?`<p class="inline-note">Kontakt demo pacijenta: ${esc(b.patient.name)} · ${esc(b.patient.phone)} · ${esc(b.patient.email)}</p>`:''}${b.status==='booked'?`<br><button class="slot" data-complete="${i}" ${Date.parse(b.startsAt)>Date.now()?'disabled':''}>Označi kao obavljeno</button>${Date.parse(b.startsAt)>Date.now()?'<p class="inline-note">Moguće tek nakon početka termina.</p>':''}`:''}</article>`).join('')||'<p class="inline-note">Nema demo rezervacija.</p>'}`;$('#portal-content').querySelectorAll('[data-toggle]').forEach(button=>button.onclick=()=>portalAction(button,'/api/portal/slots',{slotId:data.slots[Number(button.dataset.toggle)].id,enabled:!data.slots[Number(button.dataset.toggle)].enabled}));$('#portal-content').querySelectorAll('[data-complete]').forEach(button=>button.onclick=()=>portalAction(button,'/api/portal/complete',{bookingId:data.bookings[Number(button.dataset.complete)].id}))}
async function portalAction(button,path,body){if(portalBusy)return;portalBusy=true;button.disabled=true;$('#portal-clinic').disabled=true;$('#partner-dialog .close').disabled=true;$('#portal-error').textContent='';try{await api(path,{method:'POST',body:JSON.stringify(body)});await Promise.all([loadPortal(portalClinic),loadOffers(),loadBookings(),loadReminders()])}catch(error){$('#portal-error').textContent=error.message;button.disabled=false;if(error.status===409){await loadPortal(portalClinic);$('#portal-error').textContent=error.message}}finally{portalBusy=false;$('#portal-clinic').disabled=true;$('#partner-dialog .close').disabled=false}}
function resetFilters(){$('#day').value='all';$('#price').value='30000';$('#sort').value='soon';$('#district').value='';$('#min-rating').value='';$('#doctor-query').value='';$('#doctor-all').checked=true;$('#last-minute').checked=false;return loadOffers()}
function bindEvents(){bindAuthEvents();bindLiveEvents();$('#account-dialog').addEventListener('close',clearAccountPasswords);$('#group').onchange=setServices;$('#city').onchange=()=>{setDistricts();search()};$('#search').onsubmit=e=>{e.preventDefault();search();$('#results').scrollIntoView({behavior:'smooth'})};$('#all-groups').onclick=()=>{expanded=!expanded;tiles()};document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{$('#group').value=b.dataset.group;setServices();if(b.dataset.group==='radiologija')$('#service').value='Magnetna rezonanca';search();$('#results').scrollIntoView({behavior:'smooth'})});let timer;function delayed(){clearTimeout(timer);timer=setTimeout(loadOffers,200)}$('#price').oninput=()=>{$('#price-label').textContent=money($('#price').value);delayed()};$('#doctor-query').oninput=delayed;['sort','day','district','min-rating','last-minute','doctor-all'].forEach(id=>$('#'+id).onchange=loadOffers);$('#reset').onclick=resetFilters;$('#refresh-bookings').onclick=()=>Promise.all([loadBookings(),loadReminders()]);$('#partner').onclick=openPortal;$('#portal-clinic').onchange=()=>loadPortal($('#portal-clinic').value);$('#review-form').onsubmit=submitReview;$('#cancel-back').onclick=()=>$('#cancel-dialog').close();document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>{const isBusy=()=>busy||cancelBusy||reviewBusy||portalBusy||authBusy||accountBusy||notificationBusy;d.addEventListener('cancel',e=>{if(isBusy())e.preventDefault()});d.addEventListener('click',e=>{if(e.target!==d||isBusy())return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()})})}
async function init(){if(location.protocol==='file:'){document.querySelectorAll('button,select,input,textarea').forEach(e=>e.disabled=true);$('#app-status').innerHTML='<h2>Pokrenite lokalni server</h2><p>U folderu „Balkan MedTech“ dvaput kliknite <b>POKRENI.cmd</b>, pa otvorite adresu koju pokretač prikaže. Rezervacije i portal rade preko lokalnog servera, ne direktnim otvaranjem index.html.</p>';$('#app-status').hidden=false;$('#cards').textContent='Za termine i rezervacije prvo pokrenite POKRENI.cmd.';return}$('#app-status').hidden=false;$('#app-status').textContent='Učitavanje medicinskih grupa…';$('#search').setAttribute('aria-busy','true');try{const initialEpoch=authEpoch;const [data,auth,config]=await Promise.all([api('/api/catalog'),api('/api/auth/me'),api('/api/config').catch(()=>({demoQuickLogin:false}))]);demoQuickLogin=config.demoQuickLogin===true;if(initialEpoch===authEpoch)currentUser=auth.user;renderAuth();if(!Array.isArray(data.groups)||!data.groups.length)throw new Error('Katalog nije dostupan.');groups=data.groups;districts=data.districts||{};$('#city').innerHTML=(data.cities||['Beograd','Novi Sad','Niš']).map(c=>`<option>${esc(c)}</option>`).join('');$('#group').innerHTML=groups.map(g=>`<option value="${esc(g[0])}">${esc(g[1])}</option>`).join('');setServices();setDistricts();bindEvents();$('#app-status').hidden=true;await Promise.all([search(),loadBookings(),loadReminders(),loadNotifications()]);const token=new URLSearchParams(location.search).get('cancel');if(token)confirmCancellation(currentBookings.find(b=>b.cancelToken===token)||{cancelToken:token})}catch(e){$('#app-status').replaceChildren(errorBox('Lokalni server nije dostupan. Proverite POKRENI.cmd. '+e.message,init))}finally{$('#search').setAttribute('aria-busy','false')}}function renderAuth(){const area=$('#auth-area');area.innerHTML=(currentUser?`<span class="auth-user">${esc(currentUser.name)}<small>${currentUser.role==='clinic'?'Ordinacija':'Klijent'} · lokalni demo</small><button id="auth-account" class="account-link">Moj nalog ↗</button></span><button id="auth-logout" class="logout-button">Odjava</button>`:'<button id="auth-open" class="auth-button">Prijava</button>')+(demoQuickLogin?'<div class="demo-login-controls" aria-label="Brzi ulaz u razvojni demo"><small>RAZVOJNI DEMO · BRZI ULAZ</small><button id="demo-client" type="button">Demo klijent</button><button id="demo-clinic" type="button">Demo ordinacija</button></div>':'');area.insertAdjacentHTML('beforeend',`<button id="notifications-open" class="notification-bell" aria-label="Obaveštenja"><span aria-hidden="true">♧</span> Obaveštenja <span id="notification-count" class="notification-badge" ${unreadCount?'':'hidden'}>${unreadCount}</span></button>`);$('#notifications-open').onclick=openNotifications;updateNotificationBadge();if(currentUser){$('#auth-logout').onclick=logout;$('#auth-account').onclick=openAccount}else $('#auth-open').onclick=()=>openAuth('client');if(demoQuickLogin){$('#demo-client').onclick=()=>quickLogin('client');$('#demo-clinic').onclick=()=>quickLogin('clinic')}area.querySelectorAll('button').forEach(b=>b.disabled=authBusy||accountBusy||notificationBusy);$('#account-booking-note').textContent=currentUser?.role==='client'?'Rezervacije ovog lokalnog klijentskog naloga ostaju dostupne nakon ponovne prijave. Nalog nema potvrdu e-mail adrese.':currentUser?.role==='clinic'?'Prijavljeni ste kao ordinacija. Rezervacijama pacijenata upravljate u portalu; za lični pregled prijavite se kao klijent.':'Bez naloga rezervacije su vezane za ovu sesiju pregledača. Opciono se prijavite kao klijent za istoriju na lokalnom nalogu. Prijava ili registracija prenosi samo rezervacije trenutne gostujuće sesije, nikada po e-mail adresi.';$('#portal-clinic-label').hidden=true;$('#portal-clinic').disabled=true}
function configureAuthForm(){const register=authRole==='client'&&authMode==='register',switching=Boolean(currentUser);$('#auth-title').textContent=register?'Registracija klijenta':authRole==='clinic'?'Prijava ordinacije':'Prijava klijenta';$('#auth-client-tab').setAttribute('aria-selected',String(authRole==='client'));$('#auth-clinic-tab').setAttribute('aria-selected',String(authRole==='clinic'));$('#auth-client-tab').tabIndex=authRole==='client'?0:-1;$('#auth-clinic-tab').tabIndex=authRole==='clinic'?0:-1;$('#auth-panel').setAttribute('aria-labelledby',authRole==='client'?'auth-client-tab':'auth-clinic-tab');$('#auth-name-label').hidden=!register;$('#auth-name').required=register;$('#auth-consent-label').hidden=!register;$('#auth-consent').required=register;$('#auth-switch-label').hidden=!switching;$('#auth-switch').required=switching;$('#auth-password').minLength=register?10:1;$('#auth-password').maxLength=128;$('#auth-password').autocomplete=register?'new-password':'current-password';$('#auth-password-help').textContent=register?'Izaberite posebnu demo lozinku od 10 do 128 znakova.':'Unesite lozinku lokalnog demo naloga.';$('#auth-mode-toggle').hidden=authRole==='clinic';$('#auth-mode-toggle').textContent=register?'Već imate klijentski nalog? Prijavite se':'Nemate klijentski nalog? Registrujte se';$('#auth-submit').textContent=authBusy?'Sačekajte…':register?'Napravi demo nalog':'Prijavi se';$('#auth-help').textContent=authRole==='clinic'?'Nalog za osoblje dobijate od administratora lokalnog demoa. Za početni demo nalog administrator koristi lokalni fajl data/PRIJAVA-ORDINACIJE.txt. Lozinka se ne prikazuje u aplikaciji. Javna registracija ordinacije nije dostupna.':register?'Registracija je namenjena samo klijentima. Koristite izmišljeno ime i e-mail. Rezervacije trenutne gostujuće sesije pridružiće se ovom nalogu. Nema potvrde e-mail adrese.':'Prijavite se da otvorite istoriju rezervacija svog lokalnog klijentskog naloga. Rezervacije trenutne gostujuće sesije prenose se pri uspešnoj prijavi. Rezervacije se ne preuzimaju samo na osnovu e-mail adrese.';if(switching)$('#auth-help').textContent+=' Trenutno ste prijavljeni kao '+currentUser.name+' ('+(currentUser.role==='clinic'?'ordinacija':'klijent')+'). Uspešna prijava menja aktivni nalog; podaci postojećeg naloga ostaju sačuvani.'}
function openAuth(role='client',forPortal=false){if(busy||cancelBusy||reviewBusy||portalBusy||authBusy||accountBusy||notificationBusy){$('#booking-status').textContent='Sačekajte da se trenutna radnja završi.';return}authRole=role;authMode='login';authPortal=forPortal;$('#auth-form').reset();$('#auth-error').textContent='';$('#auth-password').type='password';$('#auth-show-password').textContent='Prikaži';$('#auth-show-password').setAttribute('aria-pressed','false');$('#auth-show-password').setAttribute('aria-label','Prikaži lozinku');$('#auth-reset-note').hidden=true;$('#auth-reset-help').setAttribute('aria-expanded','false');configureAuthForm();if(!$('#auth-dialog').open)$('#auth-dialog').showModal()}
function openPortal(){if(currentUser?.role==='clinic'){$('#partner-dialog').showModal();loadPortal()}else openAuth('clinic',true)}
function setAuthBusy(value){authBusy=value;$('#auth-dialog').setAttribute('aria-busy',String(value));$('#auth-dialog').querySelectorAll('input,button').forEach(el=>el.disabled=value);$('#auth-area').setAttribute('aria-busy',String(value));$('#auth-area').querySelectorAll('button').forEach(el=>el.disabled=value);if(!value)configureAuthForm();else $('#auth-submit').textContent='Sačekajte…'}
function invalidatePrivateUI(){authEpoch++;bookingRequest++;reminderRequest++;portalRequest++;accountRequest++;notificationRequest++;notificationItems=[];unreadCount=0;portalDate='';portalEditing=false;accountEditing=false;lastPortalData=null;bookingSignature='';currentBookings=[];accountProfile=null;portalClinic='';['#booking','#cancel-dialog','#review-dialog','#partner-dialog','#account-dialog','#notifications-dialog','#decision-dialog'].forEach(s=>{if($(s).open)$(s).close()});$('#booking-content').textContent='';$('#booking-list').textContent='Osvežavanje rezervacija…';$('#reminder-list').textContent='Osvežavanje podsetnika…';$('#portal-content').textContent='Prijavite se kao ordinacija za pristup portalu.';$('#portal-account').textContent='';$('#notifications-list').textContent='';$('#notifications-status').textContent='';$('#portal-date').value='';$('#decision-reason').value='';updateNotificationBadge();$('#account-content').innerHTML='<h2 id="account-title">Moj nalog</h2>';$('#booking-status').textContent='';$('#cancel-error').textContent='';$('#cancel-description').textContent='';$('#portal-clinic').innerHTML='';reviewBookingId='';$('#auth-form').reset();$('#auth-help').textContent='';$('#auth-error').textContent='';$('#review-comment').value='';$('#review-error').textContent=''}
async function applyUser(user){invalidatePrivateUI();currentUser=user;renderAuth();await Promise.all([loadBookings(),loadReminders(),loadOffers(),loadProfileCache(),loadNotifications()])}
async function submitAuth(e){e.preventDefault();if(authBusy)return;const register=authRole==='client'&&authMode==='register';if(currentUser&&!$('#auth-switch').checked){$('#auth-error').textContent='Potvrdite promenu aktivnog naloga.';return}if(register&&!$('#auth-consent').checked){$('#auth-error').textContent='Potrebna je saglasnost za čuvanje demo podataka.';return}const email=$('#auth-email').value.trim(),password=$('#auth-password').value,name=$('#auth-name').value.trim();if(!email||!password||(register&&(password.length<10||password.length>128||name.length<2))){$('#auth-error').textContent='Proverite unete podatke. Nova lozinka mora imati 10–128 znakova, a ime bar 2 znaka.';return}const nextPortal=authPortal;setAuthBusy(true);$('#auth-error').textContent='';try{const payload=register?{name,email,password,consent:true}:{email,password,role:authRole};const {user}=await api(register?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(payload)});$('#auth-password').value='';$('#auth-form').reset();$('#auth-dialog').close();await applyUser(user);authChannel?.postMessage({type:'auth-change'});$('#booking-status').textContent=user.role==='clinic'?'Prijavljeni ste kao ordinacija.':'Prijava je uspešna. Prikazane su rezervacije vašeg lokalnog naloga.';if(nextPortal&&user.role==='clinic'){$('#partner-dialog').showModal();await loadPortal()}}catch(error){$('#auth-password').value='';$('#auth-error').textContent=error.status===401?'E-mail, lozinka ili vrsta naloga nisu ispravni.':error.status===409?'Nalog sa ovim e-mailom već postoji. Prijavite se ili koristite drugi demo e-mail.':error.message}finally{setAuthBusy(false)}if(currentUser?.role==='client'&&!$('#auth-dialog').open)await openAccount()}
async function logout(){if(authBusy||busy||cancelBusy||reviewBusy||portalBusy||accountBusy||notificationBusy){$('#booking-status').textContent='Sačekajte završetak trenutne radnje pre odjave.';return}authBusy=true;$('#auth-area').setAttribute('aria-busy','true');$('#auth-logout').disabled=true;try{await api('/api/auth/logout',{method:'POST',body:JSON.stringify({})});await applyUser(null);authChannel?.postMessage({type:'auth-change'});$('#booking-status').textContent='Odjavljeni ste. Privatni podaci naloga su uklonjeni iz prikaza.'}catch(error){$('#booking-status').textContent='Odjava nije uspela. '+error.message}finally{authBusy=false;$('#auth-area').setAttribute('aria-busy','false');renderAuth()}}
function bindAuthEvents(){$('#auth-reset-help').onclick=()=>{const note=$('#auth-reset-note');note.hidden=!note.hidden;$('#auth-reset-help').setAttribute('aria-expanded',String(!note.hidden))};$('#auth-client-tab').onclick=()=>{if(authBusy)return;authRole='client';authMode='login';$('#auth-error').textContent='';$('#auth-password').value='';$('#auth-switch').checked=false;configureAuthForm()};$('#auth-clinic-tab').onclick=()=>{if(authBusy)return;authRole='clinic';authMode='login';$('#auth-error').textContent='';$('#auth-password').value='';$('#auth-switch').checked=false;configureAuthForm()};['#auth-client-tab','#auth-clinic-tab'].forEach(s=>$(s).onkeydown=e=>{if((e.key==='ArrowLeft'||e.key==='ArrowRight')&&!authBusy){e.preventDefault();const target=s==='#auth-client-tab'?'#auth-clinic-tab':'#auth-client-tab';$(target).click();$(target).focus()}});$('#auth-mode-toggle').onclick=()=>{if(authBusy||authRole!=='client')return;authMode=authMode==='login'?'register':'login';$('#auth-error').textContent='';$('#auth-password').value='';$('#auth-consent').checked=false;configureAuthForm()};$('#auth-show-password').onclick=()=>{const visible=$('#auth-password').type==='password';$('#auth-password').type=visible?'text':'password';$('#auth-show-password').textContent=visible?'Sakrij':'Prikaži';$('#auth-show-password').setAttribute('aria-pressed',String(visible));$('#auth-show-password').setAttribute('aria-label',visible?'Sakrij lozinku':'Prikaži lozinku')};$('#auth-form').onsubmit=submitAuth;$('#auth-dialog').addEventListener('close',()=>{$('#auth-password').value='';$('#auth-password').type='password';$('#auth-show-password').setAttribute('aria-pressed','false');$('#auth-show-password').setAttribute('aria-label','Prikaži lozinku');$('#auth-show-password').textContent='Prikaži'})}function userIdentity(user){return user?[user.id,user.role,user.clinicId||''].join('|'):''}
async function syncAuth(force=false){if(authBusy||busy||cancelBusy||reviewBusy||portalBusy||accountBusy||notificationBusy){clearTimeout(authSyncTimer);authSyncTimer=setTimeout(()=>syncAuth(force),350);return}const id=++authSyncRequest,epoch=authEpoch;try{const {user}=await api('/api/auth/me');if(id!==authSyncRequest||epoch!==authEpoch)return;if(force||userIdentity(user)!==userIdentity(currentUser)){await applyUser(user);$('#booking-status').textContent='Aktivni lokalni nalog je osvežen.'}}catch(error){if(id===authSyncRequest&&epoch===authEpoch&&force){invalidatePrivateUI();currentUser=null;renderAuth();$('#booking-status').textContent='Nije moguće potvrditi prijavu. Pokušajte ponovo putem dugmeta Prijava.'}}}
function setupAuthSync(){if(typeof window==='undefined'||location.protocol==='file:')return;window.addEventListener('focus',()=>syncAuth());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncAuth()});if(typeof BroadcastChannel==='function'){try{authChannel=new BroadcastChannel('balkan-medtech-local-auth');authChannel.onmessage=e=>{if(e.data?.type!=='auth-change')return;if(authBusy||busy||cancelBusy||reviewBusy||portalBusy||accountBusy||notificationBusy){syncAuth();return}invalidatePrivateUI();currentUser=null;renderAuth();syncAuth(true)}}catch{authChannel=null}}}async function loadProfileCache(){if(!currentUser)return;const epoch=authEpoch,id=currentUser.id;try{const data=await api('/api/account');if(epoch===authEpoch&&id===currentUser?.id)accountProfile=data.profile}catch{if(epoch===authEpoch)accountProfile=null}}
async function quickLogin(role){if(!demoQuickLogin||authBusy||busy||cancelBusy||reviewBusy||portalBusy||accountBusy||notificationBusy)return;authBusy=true;$('#auth-area').setAttribute('aria-busy','true');$('#auth-area').querySelectorAll('button').forEach(b=>b.disabled=true);try{const {user}=await api('/api/auth/demo-login',{method:'POST',body:JSON.stringify({role})});if($('#auth-dialog').open)$('#auth-dialog').close();$('#auth-password').value='';await applyUser(user);authChannel?.postMessage({type:'auth-change'});$('#booking-status').textContent='Brzi ulaz: '+(role==='clinic'?'demo ordinacija':'demo klijent')+'.'}catch(error){$('#booking-status').textContent='Brzi demo ulaz nije uspeo. '+error.message;return}finally{authBusy=false;$('#auth-area').setAttribute('aria-busy','false');renderAuth()}await openAccount()}
async function openAccount(){if(!currentUser){openAuth('client');return}if(authBusy||accountBusy||notificationBusy||busy||cancelBusy||reviewBusy||portalBusy)return;const id=++accountRequest,epoch=authEpoch,userId=currentUser.id;$('#account-content').innerHTML='<h2 id="account-title">Učitavanje naloga…</h2>';$('#account-dialog').setAttribute('aria-busy','true');accountEditing=false;if(!$('#account-dialog').open)$('#account-dialog').showModal();try{const account=await api('/api/account');let bookings=[];if(currentUser?.role==='client')({bookings}=await api('/api/bookings'));if(id!==accountRequest||epoch!==authEpoch||currentUser?.id!==userId)return;accountProfile=account.profile;renderAccount(account,bookings)}catch(error){if(id!==accountRequest||epoch!==authEpoch)return;$('#account-content').innerHTML='<h2 id="account-title">Moj nalog nije učitan</h2>';$('#account-content').append(errorBox(error.message,openAccount));if(error.status===401)await syncAuth()}finally{if(id===accountRequest&&epoch===authEpoch)$('#account-dialog').setAttribute('aria-busy','false')}}
function miniBookings(bookings){if(!bookings.length)return '<p class="inline-note">Još nema demo rezervacija u ovoj grupi.</p>';return bookings.map(b=>`<article class="account-mini-booking"><b>${esc(b.service)}</b><br>${esc(b.clinic)} · ${esc(date(b.startsAt))}<br>${esc(statusText(b.status))} · ${esc(money(b.cost))}${b.status==='rejected'?`<div class="rejection-note">${esc(b.rejectionReason||'Razlog odbijanja nije naveden.')}</div>`:''}${b.status==='completed'&&!b.reviewed?`<button class="slot" data-account-review="${esc(b.id)}">Ostavi recenziju</button>`:b.reviewed?'<br><small>Recenzija je sačuvana.</small>':''}</article>`).join('')}
function renderAccount(data,bookings){const u=data.user,p=data.profile||{},stats=data.stats||{},clinic=data.clinic,client=u.role==='client',cities=[...new Set(['',p.city||'',...Object.keys(districts)])],upcoming=bookings.filter(b=>['pending','booked'].includes(b.status)&&Date.parse(b.startsAt)>=Date.now()).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt)),history=bookings.filter(b=>!upcoming.includes(b)).sort((a,b)=>Date.parse(b.startsAt)-Date.parse(a.startsAt));$('#account-content').innerHTML=`<div class="eyebrow">${client?'KLIJENTSKI':'ORDINACIJSKI'} LOKALNI NALOG</div><h2 id="account-title">${esc(u.name)}</h2><p class="account-role">${esc(u.email)} · ${client?'Klijent':'Ordinacija'}<br>Lokalni demo nalog bez potvrde e-mail adrese. Koristite izmišljene podatke.</p><div id="account-status" class="account-status" role="status" aria-live="polite"></div><div id="account-live-hint" class="account-live-hint" role="status" hidden></div><div class="account-stats"><div><strong>${esc(stats.upcoming??0)}</strong>Predstojeći</div><div><strong>${esc(stats.completed??0)}</strong>Obavljeni</div><div><strong>${esc(stats.cancelled??0)}</strong>Otkazani</div><div><strong>${esc(stats.reviews??0)}</strong>Recenzije</div></div><div class="account-actions">${client?'<button id="account-bookings" class="text-button">Sve rezervacije i otkazivanje ↗</button>':'<button id="account-portal" class="primary">Otvori dashboard ordinacije ↗</button>'}<button id="account-export" class="text-button">Preuzmi moje podatke (JSON) ↓</button><button id="account-logout" class="text-button">Odjavi se</button></div><p class="export-note">Izvoz sadrži podatke ovog naloga, njegove rezervacije i recenzije. Fajl se preuzima lokalno; nema slanja spoljnim servisima.</p><div class="account-grid"><section class="account-section"><h3>Moj profil</h3><form id="account-profile-form" class="stack-form"><label>Demo ime i prezime<input id="account-name" type="text" value="${esc(u.name)}" minlength="2" maxlength="100" required autocomplete="off"></label><label>Demo telefon<input id="account-phone" type="tel" value="${esc(p.phone||'')}" maxlength="30" autocomplete="off"></label><label>Grad<select id="account-city">${cities.map(c=>`<option value="${esc(c)}" ${c===(p.city||'')?'selected':''}>${esc(c||'Nije izabran')}</option>`).join('')}</select></label><label class="check"><input id="account-sms" type="checkbox" ${p.preferences?.sms?'checked':''}> Želim demo SMS podsetnike</label><label class="check"><input id="account-viber" type="checkbox" ${p.preferences?.viber?'checked':''}> Želim demo Viber podsetnike</label><p class="inline-note">Podešavanja važe za lokalni demo. SMS i Viber nisu povezani i poruke se ne šalju.</p><div id="account-profile-error" class="account-error" role="alert"></div><button class="primary" type="submit">Sačuvaj profil</button></form></section><section class="account-section"><h3>E-mail i lozinka</h3><form id="account-email-form" class="stack-form"><label>Novi demo e-mail<input id="account-email" type="email" value="${esc(u.email)}" maxlength="254" required autocomplete="off"></label><label>Trenutna lozinka<input id="account-email-password" type="password" maxlength="128" required autocomplete="current-password"></label><p class="inline-note">Promena je lokalna; nema potvrde adrese e-mailom.</p><div id="account-email-error" class="account-error" role="alert"></div><button class="primary" type="submit">Promeni e-mail</button></form><form id="account-password-form" class="stack-form"><label>Trenutna lozinka<input id="account-current-password" type="password" maxlength="128" required autocomplete="current-password"></label><label>Nova demo lozinka<input id="account-new-password" type="password" minlength="10" maxlength="128" required autocomplete="new-password"></label><label>Ponovite novu lozinku<input id="account-confirm-password" type="password" minlength="10" maxlength="128" required autocomplete="new-password"></label><p class="inline-note">Nova lozinka od 10 do 128 znakova. Ostale prijave naloga biće odjavljene. Za zaboravljenu lozinku administrator koristi lokalni RESET-LOZINKE.cmd; nema e-mail oporavka.</p><div id="account-password-error" class="account-error" role="alert"></div><button class="primary" type="submit">Promeni lozinku</button></form></section>${client?`<section class="account-section"><h3>Predstojeće rezervacije</h3>${miniBookings(upcoming)}</section><section class="account-section"><h3>Istorija i recenzije</h3>${miniBookings(history)}</section>`:clinic?`<section class="account-section full"><h3>Profil moje ordinacije</h3><p class="inline-note">Izmene se prikazuju u javnom lokalnom profilu ordinacije i ponudi. Svi podaci treba da ostanu izmišljeni.</p><form id="account-clinic-form" class="stack-form"><label>Naziv demo ordinacije<input id="clinic-edit-name" type="text" value="${esc(clinic.name)}" minlength="2" maxlength="120" required></label><label>Demo adresa<input id="clinic-edit-address" type="text" value="${esc(clinic.address||'')}" maxlength="200"></label><label>Demo telefon<input id="clinic-edit-phone" type="tel" value="${esc(clinic.phone||'')}" maxlength="30"></label><label>Opis<textarea id="clinic-edit-description" maxlength="1000" rows="4">${esc(clinic.description||'')}</textarea></label><label>Parking<input id="clinic-edit-parking" type="text" value="${esc(clinic.parking||'')}" maxlength="200"></label><label class="check"><input id="clinic-edit-accessible" type="checkbox" ${clinic.accessible?'checked':''}> Pristupačan ulaz (demo podatak)</label><div id="account-clinic-error" class="account-error" role="alert"></div><button class="primary" type="submit">Sačuvaj profil ordinacije</button></form></section>`:''}<section class="account-section full"><h3>Prijavljene sesije</h3><p class="inline-note">Samo sesije ovog naloga. Ne prikazuju se kolačići ili tajni tokeni.</p><button id="account-revoke-others" class="text-button">Odjavi sve ostale sesije</button><div id="account-sessions-error" class="account-error" role="alert"></div>${(data.sessions||[]).map((s,i)=>`<article class="account-session">${s.current?'<span class="status-badge">Ova sesija</span><br>':''}Prijava: ${esc(date(s.createdAt))}<br>Ističe: ${esc(date(s.expiresAt))}${!s.current?`<br><button class="slot" data-revoke-session="${i}">Odjavi ovu sesiju</button>`:''}</article>`).join('')||'<p>Nema podataka o sesijama.</p>'}</section></div>`;$('#account-logout').onclick=()=>{if(!accountBusy){$('#account-dialog').close();logout()}};$('#account-export').onclick=exportAccount;if(client)$('#account-bookings').onclick=()=>{$('#account-dialog').close();loadBookings();$('#my-bookings').scrollIntoView({behavior:'smooth'})};else $('#account-portal').onclick=()=>{$('#account-dialog').close();openPortal()};$('#account-content').querySelectorAll('[data-account-review]').forEach(b=>b.onclick=()=>{const booking=bookings.find(record=>record.id===b.dataset.accountReview);if(booking){$('#account-dialog').close();openReview(booking)}});$('#account-profile-form').onsubmit=e=>{e.preventDefault();accountMutation('/api/account/profile','PATCH',{name:$('#account-name').value.trim(),phone:$('#account-phone').value.trim(),city:$('#account-city').value,preferences:{sms:$('#account-sms').checked,viber:$('#account-viber').checked}},'#account-profile-error','Profil je sačuvan.')};$('#account-email-form').onsubmit=e=>{e.preventDefault();accountMutation('/api/account/email','POST',{email:$('#account-email').value.trim(),currentPassword:$('#account-email-password').value},'#account-email-error','E-mail je promenjen. Nema potvrde adrese e-mailom.')};$('#account-password-form').onsubmit=e=>{e.preventDefault();const next=$('#account-new-password').value;if(next.length<10||next.length>128||next!==$('#account-confirm-password').value){$('#account-password-error').textContent='Nova lozinka mora imati 10–128 znakova i oba unosa moraju biti jednaka.';return}accountMutation('/api/account/password','POST',{currentPassword:$('#account-current-password').value,newPassword:next},'#account-password-error','Lozinka je promenjena. Ostale sesije su odjavljene.')};if(clinic)$('#account-clinic-form').onsubmit=e=>{e.preventDefault();accountMutation('/api/portal/profile','PATCH',{name:$('#clinic-edit-name').value.trim(),address:$('#clinic-edit-address').value.trim(),phone:$('#clinic-edit-phone').value.trim(),description:$('#clinic-edit-description').value.trim(),parking:$('#clinic-edit-parking').value.trim(),accessible:$('#clinic-edit-accessible').checked},'#account-clinic-error','Profil ordinacije je sačuvan.')};$('#account-revoke-others').onclick=()=>accountMutation('/api/account/sessions/revoke-others','POST',{},'#account-sessions-error','Ostale sesije su odjavljene.');$('#account-content').querySelectorAll('[data-revoke-session]').forEach(button=>button.onclick=()=>accountMutation('/api/account/sessions/'+encodeURIComponent(data.sessions[Number(button.dataset.revokeSession)].id),'DELETE',undefined,'#account-sessions-error','Izabrana sesija je odjavljena.'))}
function setAccountBusy(value){accountBusy=value;$('#account-dialog').setAttribute('aria-busy',String(value));$('#account-dialog').querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=value);$('#auth-area').querySelectorAll('button').forEach(el=>el.disabled=value||authBusy)}
function clearAccountPasswords(){['#account-email-password','#account-current-password','#account-new-password','#account-confirm-password'].forEach(s=>{if($(s))$(s).value=''})}
async function accountMutation(path,method,body,errorSelector,message){if(accountBusy||!currentUser)return;const epoch=authEpoch;setAccountBusy(true);$(errorSelector).textContent='';try{const result=await api(path,{method,...(body===undefined?{}:{body:JSON.stringify(body)})});if(epoch!==authEpoch)return;let user=result.user;if(!user&&result.current){await applyUser(null);authChannel?.postMessage({type:'auth-change'});return}if(!user)({user}=await api('/api/auth/me'));if(epoch!==authEpoch)return;clearAccountPasswords();await applyUser(user);authChannel?.postMessage({type:'auth-change'});setAccountBusy(false);await openAccount();if($('#account-status'))$('#account-status').textContent=message;}catch(error){if(epoch===authEpoch&&$(errorSelector))$(errorSelector).textContent=error.status===401?'Trenutna lozinka ili prijava nije ispravna.':error.status===409?'E-mail ili podaci su već zauzeti. Proverite unos.':error.message;}finally{clearAccountPasswords();setAccountBusy(false)}}
async function exportAccount(){if(accountBusy||!currentUser)return;const epoch=authEpoch;setAccountBusy(true);$('#account-status').textContent='Priprema lokalnog izvoza…';let url;try{const data=await api('/api/account/export');if(epoch!==authEpoch)return;const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='balkan-medtech-moj-nalog.json';document.body.append(link);link.click();link.remove();$('#account-status').textContent='Lokalni JSON izvoz je pripremljen za preuzimanje.';}catch(error){if(epoch===authEpoch)$('#account-status').textContent='Izvoz nije uspeo. '+error.message}finally{if(url)setTimeout(()=>URL.revokeObjectURL(url),1000);setAccountBusy(false)}}
